<script lang="ts" setup>
import { computed,onMounted,ref } from 'vue';
import { useRouter } from 'vue-router';
import { Alert as AAlert, Button as AButton, Card as ACard, Form as AForm, FormItem as AFormItem, Input as AInput, Select as ASelect, Space as ASpace, Switch as ASwitch, Table as ATable, Tabs as ATabs, TabPane as ATabPane, Tag as ATag, message } from 'ant-design-vue';
import { type PageResult,useServerPagination } from '#/utils/server-pagination';
type Center={id:string;code:string;name:string};type Node={id:string;name:string;protocol:string;host:string;servicePort:number;enabled:boolean};type Server={id:string;domain:string;listenPort:number;sslEnabled:boolean;upstreamId?:string;rootPath?:string;hideVersion:boolean;responseHeaders:string[]};
const router=useRouter(),centers=ref<Center[]>([]),nodes=ref<Node[]>([]),rows=ref<Server[]>([]),centerId=ref<string>(),nodeId=ref<string>(),active=ref('basic'),loading=ref(false);const pager=useServerPagination();const settings=ref({rootPath:'',hideVersion:true,responseHeaders:['X-Frame-Options: SAMEORIGIN','X-Content-Type-Options: nosniff','Referrer-Policy: strict-origin-when-cross-origin']});
const center=computed(()=>centers.value.find(v=>v.id===centerId.value));const node=computed(()=>nodes.value.find(v=>v.id===nodeId.value));const columns=[{dataIndex:'domain',key:'domain',title:'域名'},{dataIndex:'listenPort',key:'listenPort',title:'监听端口',width:120},{key:'ssl',title:'TLS',width:100},{key:'root',title:'root 目录'},{key:'action',title:'操作',width:150}];
async function request<T>(path:string,options?:RequestInit):Promise<T>{const r=await fetch(`/api${path}`,{...options,headers:{'Content-Type':'application/json',...(options?.headers??{})}});if(!r.ok){const b=await r.json().catch(()=>({}));throw new Error(b.detail||b.message||'请求失败')}return r.status===204?undefined as T:r.json() as Promise<T>}
async function loadServers(){if(!centerId.value)return;rows.value=pager.apply(await request<PageResult<Server>>(`/centers/${centerId.value}/http/servers/paged?${pager.query()}`))}
async function selectCenter(id:string){centerId.value=id;pager.reset();try{const values=await Promise.all([request<Node[]>(`/centers/${id}/nodes`),request<any>(`/centers/${id}/http/settings`)]);[nodes.value,settings.value]=values as any;nodeId.value=nodes.value.find(v=>v.enabled)?.id||nodes.value[0]?.id;await loadServers()}catch(e){message.error(e instanceof Error?e.message:'加载 HTTP 配置失败')}}
async function save(){if(!centerId.value)return;try{await request(`/centers/${centerId.value}/http/settings`,{method:'PUT',body:JSON.stringify(settings.value)});message.success('HTTP 块指令已保存，发布后生效')}catch(e){message.error(e instanceof Error?e.message:'保存失败')}}
function openServer(record:Server){router.push({path:'/openresty/http-servers',query:{centerId:centerId.value,nodeId:nodeId.value,serverId:record.id}})}
onMounted(async()=>{try{centers.value=await request<Center[]>('/centers');if(centers.value[0])await selectCenter(centers.value[0].id)}catch(e){message.error(e instanceof Error?e.message:'加载中心失败')}});
</script>
<template><div class="ops-page http-overview"><a-card :bordered="false" title="HTTP 块配置"><a-form layout="inline"><a-form-item label="配置中心"><a-select v-model:value="centerId" class="w-72" :options="centers.map(v=>({value:v.id,label:`${v.name}（${v.code}）`}))" @change="selectCenter"/></a-form-item><a-form-item label="OpenResty 实例"><a-select v-model:value="nodeId" class="w-96" :options="nodes.map(v=>({value:v.id,label:`${v.name}（${v.protocol} · ${v.host}:${v.servicePort}）`}))"/></a-form-item></a-form><a-alert class="mt-4" type="info" show-icon :message="`配置层级：${center?.name||'—'} → ${node?`${node.name}（${node.host}:${node.servicePort}）`:'全部实例'} → http {}`" description="此处只维护 http 块指令。Upstream 与 Server 是独立子配置块。"/></a-card><a-tabs v-model:active-key="active" class="http-level-tabs mt-4"><a-tab-pane key="basic" tab="基础与性能"><a-card :bordered="false" title="基础与性能"><a-alert type="info" show-icon message="基础文件服务与连接性能参数在发布时生成 http 块配置。"/><a-form layout="vertical" class="mt-4"><a-form-item label="全局 root 内容目录"><a-input v-model:value="settings.rootPath" placeholder="/srv/openresty-content"/></a-form-item><a-form-item label="版本信息"><a-switch v-model:checked="settings.hideVersion" checked-children="隐藏" un-checked-children="显示"/> <span class="ml-2 text-gray-500">使用 headers-more 清除 Server 响应头</span></a-form-item><a-button type="primary" @click="save">保存基础配置</a-button></a-form></a-card></a-tab-pane><a-tab-pane key="security" tab="日志与安全"><a-card :bordered="false" title="日志与安全"><a-form layout="vertical"><a-form-item label="全局响应头与安全头" extra="格式：Header-Name: value。渲染时自动带 always。"><a-select v-model:value="settings.responseHeaders" mode="tags" :token-separators="[',']"/></a-form-item><a-button type="primary" @click="save">保存日志与安全配置</a-button></a-form></a-card></a-tab-pane><a-tab-pane key="request" tab="请求处理与客户端限制"><a-card :bordered="false" title="请求处理与客户端限制"><a-alert type="info" show-icon message="请求大小、方法、Content-Type、限速与访问策略属于 Server / Location 作用域，请从 Server 详情进入对应 Location 配置。"/></a-card></a-tab-pane><a-tab-pane key="dns" tab="DNS 与连接控制"><a-card :bordered="false" title="DNS 与连接控制"><a-space><a-button type="primary" @click="router.push('/openresty/dns-resolvers')">管理 DNS Resolver</a-button><a-button @click="router.push('/openresty/upstreams')">管理 Upstream 与健康检查</a-button></a-space><a-alert class="mt-4" type="info" show-icon message="Resolver 可在 HTTP、Server、Location 和 Stream 作用域配置；Upstream 的 resolve 会自动使用共享内存区。"/></a-card></a-tab-pane><a-tab-pane key="server" tab="Server 块"><a-card :bordered="false" title="HTTP Server"><template #extra><a-button @click="router.push('/openresty/upstreams')">前往 Upstream 配置</a-button></template><a-table :columns="columns" :data-source="rows" :loading="loading" :pagination="pager.table.value" row-key="id" @change="(p:any)=>{pager.change(p);loadServers()}"><template #bodyCell="{column,record}"><template v-if="column.key==='ssl'"><a-tag :color="record.sslEnabled?'green':'default'">{{record.sslEnabled?'已启用':'未启用'}}</a-tag></template><template v-else-if="column.key==='root'">{{record.rootPath||'继承 HTTP 配置'}}</template><template v-else-if="column.key==='action'"><a-button type="link" @click="openServer(record)">进入 Server 配置</a-button></template></template></a-table></a-card></a-tab-pane></a-tabs></div></template>
<style scoped>:deep(.ant-table-wrapper){width:100%}:deep(.http-level-tabs .ant-tabs-nav){margin-bottom:12px;padding:0 12px;border-radius:6px;background:var(--ant-color-bg-container)}:deep(.ant-tabs-content-holder){min-height:360px}</style>
